@command('git.cherryPickRef', { repository: true })
	async cherryPickRef(repository: Repository, historyItem?: SourceControlHistoryItem): Promise<void> {
		if (!historyItem) {
			return;
		}
		await repository.cherryPick(historyItem.id);
	}

